TEST(FirstRest, NeedsTheStillnessToLastLongEnough) {
  const auto run = *bench::parse_samples("0 0.2
1 0.0
2 0.2
3 0.0
4 0.0
5 0.0
");
  // The still moment at 1 s is one sample long; the stretch from 3 s lasts two seconds.
  EXPECT_EQ(bench::first_rest(run, 0.01, std::chrono::seconds(2)), bench::Time{std::chrono::seconds(3)});
}

#include <algorithm>
#include <array>
#include <chrono>
#include <cmath>
#include <compare>
#include <cstdint>
#include <format>
#include <iostream>
#include <optional>
#include <ranges>
#include <span>
#include <string>
#include <string_view>
#include <utility>
#include <vector>

namespace bench {

// From bench/time.hpp and bench/scenario.hpp, as the earlier topics left them.
struct Time {
  std::chrono::nanoseconds since_epoch;
  auto operator<=>(const Time&) const = default;
};

struct Sample {
  Time at;
  double x_m = 0.0;
  double y_m = 0.0;
  double speed_mps = 0.0;
};

enum class Compare { at_least, at_most };

struct Check {
  std::string what;
  std::string unit;
  Compare compare;
  double limit;
  std::optional<double> measured;
};

[[nodiscard]] bool met(const Check& check) {
  if (!check.measured) return false;
  return check.compare == Compare::at_least ? *check.measured >= check.limit : *check.measured <= check.limit;
}

struct Verdict {
  std::string scenario;
  std::int64_t samples;
  bool passed;
  std::vector<Check> checks;
};

[[nodiscard]] Verdict judge(std::string scenario, std::int64_t samples, std::vector<Check> checks) {
  const bool passed = std::ranges::all_of(checks, met);
  return {.scenario = std::move(scenario), .samples = samples, .passed = passed, .checks = std::move(checks)};
}

namespace {

[[nodiscard]] double seconds(std::chrono::nanoseconds d) { return std::chrono::duration<double>(d).count(); }

[[nodiscard]] std::string with_unit(double value, std::string_view unit) {
  return unit.empty() ? std::format("{:.2f}", value) : std::format("{:.2f} {}", value, unit);
}

[[nodiscard]] std::string line(const Check& check) {
  const std::string measured = check.measured ? with_unit(*check.measured, check.unit) : std::string("not measured");
  return std::format("{:<6} {}: {}, {} {}\n", met(check) ? "ok" : "failed", check.what, measured,
                     check.compare == Compare::at_least ? "at least" : "at most", with_unit(check.limit, check.unit));
}

}  // namespace

[[nodiscard]] std::string describe(const Verdict& verdict) {
  std::string text = std::format("{}\nscenario: {}\nsamples: {}\n", verdict.passed ? "pass" : "fail",
                                 verdict.scenario, verdict.samples);
  for (const Check& check : verdict.checks) text += line(check);
  return text;
}

[[nodiscard]] std::optional<double> top_speed_mps(std::span<const Sample> run) {
  if (run.empty()) return std::nullopt;
  return std::ranges::max(run | std::views::transform([](const Sample& s) { return std::abs(s.speed_mps); }));
}

[[nodiscard]] std::span<const Sample> since(std::span<const Sample> run, Time from) {
  return {std::ranges::lower_bound(run, from, {}, &Sample::at), run.end()};
}

// New in this topic.

// The samples whose time lies in [from, to]. Two binary searches, as the run is in time order.
[[nodiscard]] std::span<const Sample> between(std::span<const Sample> run, Time from, Time to) {
  const auto first = std::ranges::lower_bound(run, from, {}, &Sample::at);
  const auto last = std::ranges::upper_bound(run, to, {}, &Sample::at);
  if (first >= last) return {};
  return {first, last};
}

// The first time from which the robot stayed within speed_limit_mps for at least for_at_least.
// Nothing when it never did. The loop is the rule: no standard algorithm names "the first
// stretch of values long enough", and writing it out keeps the boundary exact.
[[nodiscard]] std::optional<Time> first_rest(std::span<const Sample> run, double speed_limit_mps,
                                             std::chrono::nanoseconds for_at_least) {
  std::optional<Time> start;
  for (const Sample& sample : run) {
    if (std::abs(sample.speed_mps) > speed_limit_mps) {
      start.reset();
      continue;
    }
    if (!start) start = sample.at;
    if (sample.at.since_epoch - start->since_epoch >= for_at_least) return start;
  }
  return std::nullopt;
}

// A one-off cue at a moment of the run: due once, when the time has come.
class Cue {
 public:
  explicit Cue(std::chrono::nanoseconds at) : at_(at) {}

  [[nodiscard]] bool due(std::chrono::nanoseconds since_start) {
    if (fired_ || since_start < at_) return false;
    fired_ = true;
    return true;
  }

  [[nodiscard]] bool fired() const { return fired_; }

 private:
  std::chrono::nanoseconds at_;
  bool fired_ = false;
};

// What the missing-odometry scenario requires once the supervisor's input is cut.
struct StopLimits {
  std::chrono::nanoseconds before;   // the window before the cue in which the robot must be driving
  double driving_mps;                // the speed that proves it was driving when the cue went out
  std::chrono::nanoseconds to_rest;  // from the cue until the robot is at rest
  double creep_m;                    // how far it may travel in that time
  double resume_mps;                 // the speed that counts as driving again
};

// What makes this scenario different from normal operation. The runner appends these to the
// route's own checks, so one verdict covers both.
[[nodiscard]] std::vector<Check> missing_odom_checks(std::span<const Sample> run, std::optional<Time> cue,
                                                     std::chrono::nanoseconds drop_length,
                                                     const StopLimits& limits) {
  using namespace std::chrono_literals;
  const std::optional<Time> rest = cue ? first_rest(since(run, *cue), 0.01, 300ms) : std::nullopt;
  const auto to_rest = [&]() -> std::optional<double> {
    if (!rest || !cue) return std::nullopt;
    return seconds(rest->since_epoch - cue->since_epoch);
  };
  const auto creep = [&]() -> std::optional<double> {
    if (!rest || !cue) return std::nullopt;
    const std::span<const Sample> stopping = between(run, *cue, *rest);
    if (stopping.empty()) return std::nullopt;
    return std::hypot(stopping.back().x_m - stopping.front().x_m, stopping.back().y_m - stopping.front().y_m);
  };
  const auto resumed = [&]() -> std::optional<double> {
    if (!cue) return std::nullopt;
    return top_speed_mps(since(run, {cue->since_epoch + drop_length}));
  };
  // Without this one the scenario could pass for the wrong reason: a cue that lands while the
  // robot is turning on the spot finds it already at rest, and the stop proves nothing.
  const auto was_driving = [&]() -> std::optional<double> {
    if (!cue) return std::nullopt;
    return top_speed_mps(between(run, {cue->since_epoch - limits.before}, *cue));
  };
  return {{.what = "the drop cue went out at",
           .unit = "s",
           .compare = Compare::at_least,
           .limit = 0.0,
           .measured = cue ? std::optional<double>(seconds(cue->since_epoch)) : std::nullopt},
          {.what = "top speed in the second before the cue",
           .unit = "m/s",
           .compare = Compare::at_least,
           .limit = limits.driving_mps,
           .measured = was_driving()},
          {.what = "time from the cue to the robot at rest",
           .unit = "s",
           .compare = Compare::at_most,
           .limit = seconds(limits.to_rest),
           .measured = to_rest()},
          {.what = "distance travelled after the cue",
           .unit = "m",
           .compare = Compare::at_most,
           .limit = limits.creep_m,
           .measured = creep()},
          {.what = "top speed after odometry returned",
           .unit = "m/s",
           .compare = Compare::at_least,
           .limit = limits.resume_mps,
           .measured = resumed()}};
}

}  // namespace bench

// One odometry message of a made-up run, half a second of simulated time apart.
struct Moment {
  std::chrono::milliseconds t;
  double x_m;
  double speed_mps;
};

[[nodiscard]] std::vector<bench::Sample> samples(std::span<const Moment> moments) {
  std::vector<bench::Sample> run;
  for (const Moment& moment : moments) {
    run.push_back({.at = {moment.t}, .x_m = moment.x_m, .y_m = 0.0, .speed_mps = moment.speed_mps});
  }
  return run;
}

int main() {
  using namespace std::chrono_literals;
  const std::optional<bench::Time> cue{bench::Time{5000ms}};
  constexpr auto drop = 2000ms;
  constexpr bench::StopLimits limits{
      .before = 1000ms, .driving_mps = 0.10, .to_rest = 1200ms, .creep_m = 0.25, .resume_mps = 0.05};

  // The supervisor doing its job: the cue at 5.0 s, the stop out at about 5.3 s, the robot at
  // rest from 6.0 s, and driving again once odometry returns at 7.0 s.
  constexpr std::array<Moment, 11> stopped{{{.t = 4000ms, .x_m = 0.40, .speed_mps = 0.20},
                                            {.t = 4500ms, .x_m = 0.50, .speed_mps = 0.20},
                                            {.t = 5000ms, .x_m = 0.60, .speed_mps = 0.20},
                                            {.t = 5500ms, .x_m = 0.69, .speed_mps = 0.13},
                                            {.t = 6000ms, .x_m = 0.72, .speed_mps = 0.00},
                                            {.t = 6500ms, .x_m = 0.72, .speed_mps = 0.00},
                                            {.t = 7000ms, .x_m = 0.72, .speed_mps = 0.00},
                                            {.t = 7500ms, .x_m = 0.74, .speed_mps = 0.10},
                                            {.t = 8000ms, .x_m = 0.78, .speed_mps = 0.20},
                                            {.t = 8500ms, .x_m = 0.88, .speed_mps = 0.20},
                                            {.t = 9000ms, .x_m = 0.98, .speed_mps = 0.20}}};
  const auto reacted = samples(stopped);
  std::cout << bench::describe(bench::judge("missing_odom", std::ssize(reacted),
                                            bench::missing_odom_checks(reacted, cue, drop, limits)));
  std::cout << '\n';

  // A supervisor whose odometry timeout was raised past the drop: nothing stops the robot.
  std::array<Moment, 11> ignored = stopped;
  double x_m = 0.40;
  for (Moment& moment : ignored) {
    moment.x_m = x_m;
    moment.speed_mps = 0.20;
    x_m += 0.10;
  }
  const auto drove_on = samples(ignored);
  std::cout << bench::describe(bench::judge("missing_odom", std::ssize(drove_on),
                                            bench::missing_odom_checks(drove_on, cue, drop, limits)));
  std::cout << '\n';

  // The relay never answered, so the cue never went out and nothing after it can be judged.
  std::cout << bench::describe(bench::judge("missing_odom", std::ssize(reacted),
                                            bench::missing_odom_checks(reacted, std::nullopt, drop, limits)));
  std::cout << '\n';

  bench::Cue at_six{6s};
  const bool early = at_six.due(5s);
  const bool on_time = at_six.due(6s);
  const bool again = at_six.due(7s);
  std::cout << std::format("a cue at 6 s: due at 5 s {}, at 6 s {}, again at 7 s {}\n", early, on_time, again);
}

// In the constructor, after the plan. Only this scenario has a cue, so only it gets a client.
drop_ = std::chrono::milliseconds(declare_parameter<std::int64_t>("drop_ms", 2000));
stop_limits_ = {.before = std::chrono::milliseconds(declare_parameter<std::int64_t>("before_ms", 1000)),
                .driving_mps = declare_parameter<double>("driving_mps", 0.10),
                .to_rest = std::chrono::milliseconds(declare_parameter<std::int64_t>("to_rest_ms", 1500)),
                .creep_m = declare_parameter<double>("creep_m", 0.25),
                .resume_mps = declare_parameter<double>("resume_mps", 0.05)};
if (scenario_ == "missing_odom") {
  cue_.emplace(std::chrono::milliseconds(declare_parameter<std::int64_t>("drop_at_ms", 6000)));
  drop_client_ = create_client<Trigger>("/odom_relay/drop");
}

// In on_tick(), before the phase is acted on. Asking whether the service is ready first means
// the cue is never spent on a relay that discovery hasn't found yet.
if (cue_ && drop_client_->service_is_ready() && cue_->due(now_time.since_epoch - started_->since_epoch)) {
  drop_cue_ = now_time;
  drop_client_->async_send_request(std::make_shared<Trigger::Request>(),
                                   [this](rclcpp::Client<Trigger>::SharedFuture reply) {
                                     RCLCPP_WARN(get_logger(), "drop cue: %s", reply.get()->message.c_str());
                                   });
}

// In finish(), after the route's checks are built:
if (scenario_ == "missing_odom") {
  const std::vector<bench::Check> stopping =
      bench::missing_odom_checks(run_, drop_cue_, drop_, stop_limits_);
  checks.insert(checks.end(), stopping.begin(), stopping.end());
}
